	static getStudentAttendanceStats(courseId, studentId) {
		const sessions = this.getAttendanceSessions(courseId);
		const totalSessions = sessions.length;
		if (totalSessions === 0) return {
			totalSessions: 0,
			presentCount: 0,
			lateCount: 0,
			excusedCount: 0,
			absentCount: 0,
			percentage: 100
		};
		let presentCount = 0;
		let lateCount = 0;
		let excusedCount = 0;
		let absentCount = 0;
		let weightedAttended = 0;
		sessions.forEach((sess) => {
			const rec = sess.records[studentId];
			const status = rec?.status || (sess.isOpen ? "absent" : "absent");
			if (rec?.status === "present") {
				presentCount++;
				weightedAttended += 1;
			} else if (rec?.status === "late") {
				lateCount++;
				weightedAttended += .85;
			} else if (rec?.status === "excused") {
				excusedCount++;
				weightedAttended += 1;
			} else if (status === "absent") absentCount++;
		});
		const percentage = Math.min(100, Math.round(weightedAttended / totalSessions * 100));
		return {
			totalSessions,
			presentCount,
			lateCount,
			excusedCount,
			absentCount,
			percentage
		};
	}
